def apply_coupon(order_amount, coupon, current_amount=None):
    # type: (int, Dict, Optional[int]) -> int
    """쿠폰 1장을 적용한 뒤의 결제 금액을 돌려준다.

    order_amount: 쿠폰 적용 전 주문 금액
    current_amount: 앞선 쿠폰까지 적용된 현재 금액 (첫 쿠폰이면 None)
    """
    if current_amount is None:
        current_amount = order_amount
    if not is_coupon_applicable(order_amount, coupon):
        return current_amount
    discount = calc_coupon_discount(current_amount, coupon)
    return max(0, current_amount - discount)

def calc_due_date(order_dt: datetime | None = None) -> date:
    """정산 지급일: 주문일(한국 시간) 기준 월말 마감 후 영업일 5일째.

    order_dt: UTC naive datetime. 없으면 현재 시각.
    """
    if order_dt is None:
        order_dt = datetime.now(timezone.utc).replace(tzinfo=None)
    local = order_dt.replace(tzinfo=timezone.utc)
    month_end = date(local.year, local.month, date_utils.last_day_of_month(local.year, local.month))
    return date_utils.add_business_days(month_end, config.SETTLEMENT_BUSINESS_DAYS)

