def calc_late_penalty(tax, days_late):
    """납부지연가산세 (1일 10만분의 22), 10원 미만 절사."""
    if tax <= 0 or days_late == 0:
        return 0
    return truncate_won(tax * days_late * LATE_PENALTY_RATE // 100000)

def calc_simplified_vat(sales, value_added_rate):
    """간이과세 세액 = 공급대가 x 업종별 부가가치율 x 10%, 10원 미만 절사."""
    if value_added_rate > VALUE_ADDED_RATE_MAX:
        raise ValueError("부가가치율 범위 오류: %d" % value_added_rate)
    if value_added_rate < VALUE_ADDED_RATE_MIN:
        return 0
    added = sales * value_added_rate // 100
    return truncate_won(added * VAT_RATE // 100)

def should_retry(error_code, attempt):
    """attempt: 지금까지 시도한 재시도 횟수."""
    if not is_retryable(error_code):
        return False
    return attempt <= MAX_RETRY_COUNT

def calc_commission_rate(grade, small_business=False):
    """판매 수수료율(천분율). 등급 우대·영세 사업자 우대 후 하한 적용."""
    rate = BASE_COMMISSION_RATE - PREFERRED_DISCOUNTS.get(grade, 0)
    if small_business:
        rate -= SMALL_BIZ_DISCOUNT
    return rate

def calc_average_rating(ratings):
    # type: (List[int]) -> float
    """평균 평점. 소수 둘째 자리에서 반올림(half-up)해 첫째 자리까지 표시.

    예: 4.05 -> 4.1, 4.04 -> 4.0. 리뷰가 없으면 0.0.
    """
    if not ratings:
        return 0.0
    total = sum(validate_rating(r) for r in ratings)
    return round(total / len(ratings), 1)

def mask_card_number(card_number):
    digits = card_number.replace("-", "").replace(" ", "")
    return digits[:4] + "*" * 8 + digits[-4:]

def split_mixed_items(items):
    # type: (List[Dict]) -> Dict[str, int]
    """과세(TAXABLE)·면세(TAX_FREE) 상품 금액 합계 분리."""
    result = {"TAXABLE": 0, "TAX_FREE": 0}
    for item in items:
        tax_type = str(item.get("tax_type", "TAXABLE")).upper()
        if tax_type not in result:
            raise ValueError("알 수 없는 과세 유형: %s" % tax_type)
        result[tax_type] += item["price"] * item["quantity"]
    return result
